import { DatabaseSync } from 'node:sqlite';
function main(): void {
  const db = new DatabaseSync(':memory:');
  console.log(JSON.stringify(db.prepare('SELECT ?1 AS a, ?2 AS b').get(1, 'two')));
  console.log(JSON.stringify(db.prepare('SELECT $n AS n').get({ n: 3 })));
  console.log(JSON.stringify(db.prepare('SELECT :x AS x, @y AS y').get({ x: 'p', y: 'q' })));
  console.log(JSON.stringify(db.prepare('SELECT ? AS a, ? AS b').get(1, null)));
  db.close();
}
